function navLink(l,p){const x=PAGES.find(y=>y.path===l[1]);return `<a href="${l[1]}"${x?` data-page="${x.id}"`:""}${x&&x.id===p.id?' aria-current="page"':""}>${esc(l[0])}</a>`}
function siteHeader(p){return `<div class="bx-sp-subbar"><div class="bar" aria-hidden="true"><i id="bar"></i></div></div>`}

const ENG=[["google","Google"],["meta","Meta"],["tiktok","TikTok"],["amazon","Amazon"]];
function stage(p,t){const q=p.q[0];
if(t==="google")return `<div class="ad g"><small>Sponsored · yourbrand.com</small><b>${esc(p.short)} that pays for itself</b><span>Clear offer. Proof. One next step.</span><div class="sl"><i>Book a call</i><i>See pricing</i><i>Case studies</i></div></div><div class="ad org"><small>rival-one.com</small><b>A competitor's page</b></div>`;
if(t==="meta")return `<div class="ad m"><div class="who"><i></i><p><b>Your Brand</b><small>Sponsored</small></p></div><p>Still paying for clicks that never buy? See how it works.</p><div class="crt"><span>Your scroll-stopping creative</span></div><div class="ctaad"><span>yourbrand.com</span><i>Learn more</i></div></div>`;
if(t==="tiktok")return `<div class="ad t"><div class="vid"><span class="hook">POV: your ads finally work</span><div class="side"><i>♥</i><i>✦</i><i>➜</i></div><p><b>@yourbrand</b><small>Sponsored · Shop now</small></p></div></div>`;
return `<div class="ad a"><div class="pimg"></div><div><small>Sponsored</small><b>Your Brand product, the one shoppers pick</b><span class="st">★★★★★</span><span class="pr">Prime · Fast delivery</span><i class="add">Add to cart</i></div></div>`}
function hero(p){const pr=p.id==="paid-media"?"":`<li><a href="/paid-media">Paid Media</a></li>`;
return `<section class="hero" id="top"><div class="wrap hg"><div class="hl"><p class="onp"><span>Campaigns on</span>${BR.map(b=>mark(b,"pop")).join("")}</p><ol class="crumb"><li><a href="/">Home</a></li>${pr}<li aria-current="page">${esc(p.short)}</li></ol>
<h1>${esc(p.h1[0])} <em>${esc(p.h1[1])}</em> ${esc(p.h1[2])}</h1><p class="lead">${esc(p.lead)}</p>
<form class="dom" data-dom><label for="dom-in">Your website</label><input id="dom-in" name="domain" type="text" inputmode="url" autocomplete="url" placeholder="yourdomain.com"><button class="btn pri" type="submit"><span>Run my free ad audit</span>${ARROW}</button></form>
<p class="tiny">Free. A media buyer reviews it personally. Or call <a href="tel:+14244416042">${TEL}</a></p></div>
<div class="hr"><div class="hs">${[0,1,2].map(i=>mark(BR[i%BR.length],"orb o"+i)).join("")}<div class="stage" data-stage><div class="sbar"><span class="dot"></span><span class="typed" data-typed>${esc(p.q[0])}</span><i class="caret"></i>${mark(BR[0],"inb")}</div>
<div class="tabs" role="tablist" aria-label="Ad channels">${ENG.map(e=>`<button role="tab" aria-selected="${e[0]===engOf(p)}" data-eng="${e[0]}">${e[0]==="amazon"&&p.id==="walmart"?"Walmart":e[0]==="amazon"&&p.id==="target"?"Target":e[1]}</button>`).join("")}</div>
<div class="sres" data-res>${stage(p,engOf(p))}</div><p class="ill">Illustration of the goal. Not a live ad.</p></div></div>${img(p,"hero",1000,420,"Live campaign dashboard",`${p.short} campaign dashboard from Beetrix360`)}</div></div></section>
<div class="proof" aria-label="Headline results"><div class="track">${Array(2).fill(["$10B+ pipeline generated","24.8M leads processed","55+ industries","Tesla Solar +40% pre-orders","Microsoft +30% engagement","Subway +25% footfall","0.4s lead response"].map(x=>`<span>${x}</span>`).join("")).join("")}</div></div><div class="rib" aria-hidden="true"><div class="rt">${Array(24).fill(0).map((_,i)=>mark(BR[i%BR.length])).join("")}</div></div><div class="logos wrap" aria-label="Client logos">${["Tesla Solar","Microsoft","Subway","Damac"].map((n,i)=>img(p,"logo-"+(i+1),240,80,n+" logo",n+" logo")).join("")}</div>`}

function guide(p){return `<section class="sec" id="guide"><div class="wrap gd"><aside class="toc" aria-label="On this page"><p class="eye">On this page</p>${[["guide","What it is"],["fixes","Problems we fix"],["included","What's included"],["score","Check your score"],["math","Ad spend calculator"],["rollout","90-day rollout"],["work","Past work"],["faq","FAQs"]].map(x=>`<a href="#${x[0]}">${x[1]}</a>`).join("")}${cta("Book a 30-minute call","ghost sm")}</aside>
<div class="prose"><h2>What is ${esc(p.what||p.kw.replace(/ services$/,""))}?</h2><p class="snip" data-answer>${esc(p.answer)}</p>${img(p,"explainer",1200,630,`Diagram: how ${p.short} funnels work`,`Diagram showing how ${p.short} works`)}
${p.para.map(x=>`<p>${esc(x)}</p>`).join("")}${p.deep.map((d,i)=>`<h3>${esc(d[0])}</h3><p>${esc(d[1])}</p>${img(p,"guide-"+(i+1),1000,520,"Screenshot or chart: "+d[0],d[0])}`).join("")}
<h3>Related topics we cover</h3><p class="hint">Tap the topics you care about. We'll add them to your media brief.</p><div class="chips">${p.kws.map(k=>`<button class="chip" aria-pressed="false" data-chip>${esc(k)}</button>`).join("")}</div>
<div class="tray" data-tray hidden><span data-traytext></span>${cta("Send this to a strategist","pri sm")}</div></div></div></section>`}

function fixes(p){return `<section class="sec tint" id="fixes"><div class="wrap">${head("Sound familiar?",`Four signs your ${esc(p.short)} is wasting budget`,"Hover or tap a card to see the fix.")}
<div class="flips">${p.pains.map((x,i)=>`<button class="flip c${i}" aria-expanded="false"><span class="f"><i>Symptom</i><b>${esc(x[0])}</b></span><span class="b"><i>The fix</i><b>${esc(x[1])}</b></span></button>`).join("")}</div>
<div class="pair">${img(p,"before",800,500,"Before: the account as we found it",`Before ${p.short} work`)}${img(p,"after",800,500,"After: the same account, fixed",`After ${p.short} work`)}</div><div class="band"><p>Recognize one of these? Each one quietly burns ad budget.</p>${cta("Audit my ad account free","pri")}</div></div></section>`}

function included(p){return `<section class="sec dark" id="included"><div class="wrap">${head("What's included",`Everything in our ${esc(p.kw)}`,`Six parts, one system. Move across a card to light it up, or tap to lock it in.`)}
<div class="bento">${p.items.map((x,i)=>`<button class="tile t${i}" aria-pressed="false">${img(p,"item-"+(i+1),640,300,x[0],x[0]+" for "+p.short,"span")}<b>${esc(x[0])}</b><span>${esc(x[1])}</span></button>`).join("")}</div>
<div class="band inv"><p><span data-lock>0</span> of 6 selected for your plan</p>${cta(`Build my ${p.short} plan`,"pri")}</div></div></section>`}

function score(p){return `<section class="sec" id="score"><div class="wrap sg"><div>${head("Self-check",`How ready is your ${esc(p.short)}?`,"Switch on what you already have in place. The first two are examples, so change them to match your site.")}
<div class="tog">${p.items.map((x,i)=>`<label class="sw"><input id="sw-${i}" type="checkbox"${i<2?" checked":""}><i></i><span>${esc(x[0])}</span></label>`).join("")}</div>${img(p,"report",1000,440,"Sample ad account audit",`Sample ${p.short} account audit`)}</div>
<div class="gauge"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="52" class="gt"/><circle cx="60" cy="60" r="52" class="gv" data-gv/></svg><p class="gn"><span data-gn>33</span><small>/100</small></p><p class="gm" data-gm></p>${cta("Plug my budget leaks","pri")}<p class="tiny">A quick self-check, not a formal audit.</p></div></div></section>`}

function math(p){const f=(id,l,mn,mx,st,v,pre,suf)=>`<label class="rg" for="m-${id}"><span>${l}<output data-o="${id}"></output></span><input id="m-${id}" type="range" min="${mn}" max="${mx}" step="${st}" value="${v}" data-m="${id}" data-pre="${pre}" data-suf="${suf}"></label>`;
return `<section class="sec dark" id="math"><div class="wrap mg"><div>${head("Ad spend calculator",`What could your ${esc(p.short)} budget return?`,"Drag the sliders to see how spend, cost per click, conversion rate and sale value connect. The starting numbers are examples, so enter your own.")}
<div class="rgs">${f("spend","Monthly ad spend",1000,100000,500,10000,"$","")}${f("cpc","Average cost per click",.25,20,.25,2,"$","")}${f("cvr","Conversion rate",.5,15,.5,3,"","%")}${f("val","Value per sale",10,5000,10,120,"$","")}</div></div>
<div class="out"><dl><div><dt>Clicks</dt><dd data-r="clicks"></dd></div><div><dt>Sales</dt><dd data-r="sales"></dd></div><div><dt>Cost per sale</dt><dd data-r="cpa"></dd></div><div><dt>Revenue</dt><dd data-r="rev"></dd></div></dl><p class="ro"><small>Return on ad spend</small>${mark(BR[0],"bob")}<b data-r="roas"></b></p><div class="rb"><i data-rb></i></div><p class="rm" data-rm></p>${cta("Model my real numbers","pri")}<p class="tiny">Simple arithmetic for planning, not a forecast of results.</p></div></div></section>`}
