function allFaq(p){const pr="/pricing/ppc-cost";
const has=p.faq.some(x=>/cost/i.test(x[0]));return {list:p.faq.concat([[`How much does ${p.what||p.kw.replace(/ services$/,"")} cost?`,`The cost depends on your site, market and goals. Our pricing guide explains what affects the price, and we provide a fixed scope after the audit.`],[`Do you guarantee results for ${p.short}?`,`No honest agency can guarantee a specific return from advertising. We commit to a clear plan, weekly progress and reporting tied to revenue.`],[`How do I get started with Beetrix360?`,`Request the free ad account audit. We'll review your site, then walk you through a 90-day plan on a 30-minute call.`]].filter((x,i)=>!(has&&i===0))),pr}}
function faq(p){const f=allFaq(p);return `<section class="sec tint" id="faq"><div class="wrap fq"><div class="fs">${head("FAQs",`${esc(p.short)} questions, answered`,"Direct answers first, with detail when you need it.")}<label class="srch" for="faq-q"><span>Search the FAQs</span><input id="faq-q" type="search" placeholder="Try “cost” or “how long”"></label><p class="tiny" data-faqn>${f.list.length} questions</p>${cta("Ask a strategist instead","ghost")}${img(p,"strategist",640,420,"Photo of your strategist",`Beetrix360 ${p.short} strategist`)}</div>
<div class="fl">${f.list.map((x,i)=>`<details data-q${i===0?" open":""}><summary><h3>${esc(x[0])}</h3><i></i></summary><p>${esc(x[1])}${/cost/i.test(x[0])?` <a href="${f.pr}">Read the pricing guide</a>.`:""}</p></details>`).join("")}<p class="none" data-none hidden>No match yet. Send us the question and a strategist will answer it.</p></div></div></section>`}

function related(p){const o=PAGES.filter(x=>x.id!==p.id&&!x.hub&&x.col===p.col).concat(PAGES.filter(x=>x.col!==p.col&&!x.hub)).slice(0,6);return `<section class="sec" id="related"><div class="wrap">${head("Keep exploring","Services that work well with this one")}
<div class="rel">${o.map(x=>`<a href="${x.path}" data-page="${x.id}">${img(p,"rel-"+x.id,560,260,x.short,x.short,"span")}<b>${esc(x.short)}</b><span>${esc(x.lead.split(". ")[0].replace(/^(.{0,110})\s.*$/,"$1…"))}</span>${ARROW}</a>`).join("")}</div><div class="band"><p>Not sure which service you need first?</p>${cta("Pick the right one for me","pri")}</div></div></section>`}

function start(p){return `<section class="sec final" id="start"><div class="wrap fg"><div><p class="eye">Free 90-day blueprint</p><h2>Let's build your ${esc(p.short)} revenue engine.</h2><p class="sub">Get an ad account audit, media plan and ROI model. We reply within 1 business day.</p><p class="tel">${TEL}</p><div class="drift" aria-hidden="true">${[0,1,2,3].map(i=>mark(BR[i%BR.length],"d"+i)).join("")}</div>${img(p,"team",900,520,"Your team photo","The Beetrix360 team")}</div>
<form class="lead-f" data-lead novalidate><div class="two"><label for="f-n">Name<input id="f-n" name="name" required autocomplete="name"></label><label for="f-e">Work email<input id="f-e" name="email" type="email" required autocomplete="email"></label></div>
<label for="f-w">Website<input id="f-w" name="website" required autocomplete="url"></label>
<label for="f-g">Main goal<select id="f-g" name="goal"><option>${esc(p.short)}</option><option>Paid search</option><option>Paid social</option><option>Amazon and marketplaces</option><option>Full-funnel media</option></select></label>
<label for="f-b">Monthly budget<select id="f-b" name="budget"><option>$5k – $10k</option><option>$10k – $25k</option><option>$25k – $50k</option><option>$50k+</option></select></label>
<label for="f-m">Anything we should know?<textarea id="f-m" name="notes" rows="3"></textarea></label>
<button class="btn pri" type="submit"><span>Get my blueprint</span>${ARROW}</button><p class="fmsg" data-msg role="status"></p></form></div></section>`}

function foot(){return `
<div class="dock"><a class="btn pri sm" href="#start"><span>Free AI audit</span>${ARROW}</a></div>
<div class="spine" aria-hidden="true"><span data-spine>${mark(BR[0])}</span>${LOGO("mark")}</div>`}

/* Paragraph blocks, filled from text-content.js */
const TXG=["The basics","Choosing the right approach","Doing it well","Results and next steps"];
function txt(p,i,raw){const a=TEXT[p.id]||[],n=Math.ceil(a.length/4),L=a.slice(i*n,(i+1)*n).filter(x=>x[2]||!HIDE_EMPTY);if(!L.length)return "";const b=`<h2 class="txh">${esc(p.short||p.name)}: ${TXG[i]}</h2><div class="txg">${L.map(x=>`<article class="txa"><h3>${esc(x[0])}</h3>${x[2]?`<p>${esc(x[2])}</p>`:`<p class="txp">Write 80 to 120 words here. Answer the topic in the first sentence, use &ldquo;${esc(x[1])}&rdquo; naturally, and add one real example.</p>`}</article>`).join("")}</div>`;return raw?b:`<section class="txs" aria-label="${TXG[i]}">${b}</section>`}
